// Canonical assignment table SQL shared with schema migration fixtures.

pub(crate) const CREDIT_BUDGET_COLUMN_SQL: &str =
    "credit_budget INTEGER CHECK(credit_budget IS NULL OR credit_budget IN (1,3,5))";

macro_rules! agent_assignments_table_sql {
    ($extra_columns:literal, $extra_constraints:literal) => {
        concat!(
            "CREATE TABLE agent_assignments (assignment_id BLOB PRIMARY KEY NOT NULL CHECK(length(assignment_id) = 16), workspace_id BLOB NOT NULL REFERENCES workspace(workspace_id) CHECK(length(workspace_id) = 16), activity_id BLOB NOT NULL REFERENCES activities(activity_id) CHECK(length(activity_id) = 16), goal_id BLOB NOT NULL REFERENCES goals(goal_id) CHECK(length(goal_id) = 16), goal_created_at_ms INTEGER NOT NULL CHECK(goal_created_at_ms >= 0), goal_revision INTEGER NOT NULL CHECK(goal_revision >= 1), dag_revision INTEGER NOT NULL CHECK(dag_revision >= 1), dag_head_revision INTEGER NOT NULL CHECK(dag_head_revision >= 1), node_id BLOB NOT NULL CHECK(length(node_id) = 16), node_revision INTEGER NOT NULL CHECK(node_revision >= 1), coordinator_agent_id BLOB NOT NULL CHECK(length(coordinator_agent_id) = 16), coordinator_session_id BLOB NOT NULL CHECK(length(coordinator_session_id) = 16), coordinator_principal_kind INTEGER NOT NULL CHECK(coordinator_principal_kind IN (0, 1, 2)), coordinator_principal_id BLOB CHECK(coordinator_principal_id IS NULL OR length(coordinator_principal_id) = 16), coordinator_revision INTEGER NOT NULL CHECK(coordinator_revision >= 1), target_agent_id BLOB NOT NULL CHECK(length(target_agent_id) = 16), target_session_id BLOB NOT NULL CHECK(length(target_session_id) = 16), target_principal_kind INTEGER NOT NULL CHECK(target_principal_kind IN (0, 1, 2)), target_principal_id BLOB CHECK(target_principal_id IS NULL OR length(target_principal_id) = 16), target_agent_revision INTEGER NOT NULL CHECK(target_agent_revision >= 1), state INTEGER NOT NULL CHECK(state IN (0, 1, 2, 3, 4, 5, 6)), cancellation_requested INTEGER NOT NULL CHECK(cancellation_requested IN (0, 1)), report TEXT CHECK(report IS NULL OR length(CAST(report AS BLOB)) BETWEEN 1 AND 32768), worktree_root_fingerprint BLOB CHECK(worktree_root_fingerprint IS NULL OR length(worktree_root_fingerprint) = 16), worktree_repository_fingerprint BLOB CHECK(worktree_repository_fingerprint IS NULL OR length(worktree_repository_fingerprint) = 16), worktree_baseline BLOB CHECK(worktree_baseline IS NULL OR length(worktree_baseline) = 20), reviewed_agent_id BLOB CHECK(reviewed_agent_id IS NULL OR length(reviewed_agent_id) = 16), reviewed_session_id BLOB CHECK(reviewed_session_id IS NULL OR length(reviewed_session_id) = 16), reviewed_principal_kind INTEGER CHECK(reviewed_principal_kind IS NULL OR reviewed_principal_kind IN (0, 1, 2)), reviewed_principal_id BLOB CHECK(reviewed_principal_id IS NULL OR length(reviewed_principal_id) = 16), reviewed_revision INTEGER CHECK(reviewed_revision IS NULL OR reviewed_revision >= 1), created_at_ms INTEGER NOT NULL CHECK(created_at_ms >= 0), updated_at_ms INTEGER NOT NULL CHECK(updated_at_ms >= created_at_ms), revision INTEGER NOT NULL CHECK(revision >= 1), credit_budget INTEGER CHECK(credit_budget IS NULL OR credit_budget IN (1,3,5))",
            $extra_columns,
            ", FOREIGN KEY(coordinator_agent_id, workspace_id, activity_id) REFERENCES agent_instances(agent_id, workspace_id, activity_id), FOREIGN KEY(target_agent_id, workspace_id, activity_id) REFERENCES agent_instances(agent_id, workspace_id, activity_id), FOREIGN KEY(reviewed_agent_id, workspace_id, activity_id) REFERENCES agent_instances(agent_id, workspace_id, activity_id), CHECK((coordinator_principal_kind = 0 AND coordinator_principal_id IS NULL) OR (coordinator_principal_kind IN (1, 2) AND coordinator_principal_id IS NOT NULL)), CHECK((target_principal_kind = 0 AND target_principal_id IS NULL) OR (target_principal_kind IN (1, 2) AND target_principal_id IS NOT NULL)), CHECK((reviewed_principal_kind IS NULL AND reviewed_principal_id IS NULL AND reviewed_agent_id IS NULL AND reviewed_session_id IS NULL AND reviewed_revision IS NULL) OR (reviewed_principal_kind IS NOT NULL AND reviewed_principal_id IS NOT NULL OR reviewed_principal_kind = 0 AND reviewed_principal_id IS NULL) AND reviewed_agent_id IS NOT NULL AND reviewed_session_id IS NOT NULL AND reviewed_revision IS NOT NULL), CHECK((worktree_root_fingerprint IS NULL AND worktree_repository_fingerprint IS NULL AND worktree_baseline IS NULL) OR (worktree_root_fingerprint IS NOT NULL AND worktree_repository_fingerprint IS NOT NULL AND worktree_baseline IS NOT NULL)), CHECK(((state IN (2, 3, 4)) AND report IS NOT NULL) OR ((state IN (0, 1, 5, 6)) AND report IS NULL)), CHECK((state IN (3, 4) AND reviewed_agent_id IS NOT NULL) OR (state NOT IN (3, 4) AND reviewed_agent_id IS NULL)), CHECK((cancellation_requested = 0 AND state IN (0, 1, 2, 3, 4)) OR (cancellation_requested = 1 AND state IN (1, 5, 6)))",
            $extra_constraints,
            ")"
        )
    };
}

/// Exact assignment-table DDL before the v74 Home origin and receipt columns.
pub(crate) const AGENT_ASSIGNMENTS_TABLE_SQL_V73: &str = agent_assignments_table_sql!("", "");

pub(crate) const AGENT_ASSIGNMENTS_TABLE_SQL: &str = agent_assignments_table_sql!(
    ", origin_kind INTEGER NOT NULL CHECK(origin_kind IN (0,1)), home_receipt_id BLOB CHECK(home_receipt_id IS NULL OR (length(home_receipt_id)=16 AND home_receipt_id!=zeroblob(16)))",
    ", CHECK((origin_kind=0 AND home_receipt_id IS NULL) OR (origin_kind=1 AND home_receipt_id IS NOT NULL)), FOREIGN KEY(home_receipt_id,origin_kind) REFERENCES home_handoff_acceptance_outcomes(acceptance_id,outcome_kind) DEFERRABLE INITIALLY DEFERRED"
);
pub(crate) const AGENT_ASSIGNMENTS_V73_COPY_COLUMNS_SQL: &str = "assignment_id, workspace_id, activity_id, goal_id, goal_created_at_ms, goal_revision, dag_revision, dag_head_revision, node_id, node_revision, coordinator_agent_id, coordinator_session_id, coordinator_principal_kind, coordinator_principal_id, coordinator_revision, target_agent_id, target_session_id, target_principal_kind, target_principal_id, target_agent_revision, state, cancellation_requested, report, worktree_root_fingerprint, worktree_repository_fingerprint, worktree_baseline, reviewed_agent_id, reviewed_session_id, reviewed_principal_kind, reviewed_principal_id, reviewed_revision, created_at_ms, updated_at_ms, revision, credit_budget";
